// Solothurn
const ORT = { lat: 47.2088, lon: 7.5323, name: "Solothurn" };


// ---------- Feiertage Kanton Solothurn ----------

// Ostersonntag nach der Gaußschen Formel
function ostersonntag(jahr) {
  const a = jahr % 19, b = Math.floor(jahr / 100), c = jahr % 100;
  const d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const monat = Math.floor((h + l - 7 * m + 114) / 31);
  const tag = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(jahr, monat - 1, tag);
}

function feiertage(jahr) {
  const o = ostersonntag(jahr);
  const ab = (n) => {
    const d = new Date(o); d.setDate(d.getDate() + n); return isoDatum(d);
  };
  const fest = (m, t) => isoDatum(new Date(jahr, m - 1, t));

  return [
    { datum: fest(1, 1),   name: "Neujahr" },
    { datum: fest(1, 2),   name: "Berchtoldstag" },
    { datum: fest(3, 19),  name: "Josefstag" },
    { datum: ab(-2),       name: "Karfreitag" },
    { datum: ab(1),        name: "Ostermontag" },
    { datum: fest(5, 1),   name: "Tag der Arbeit" },
    { datum: ab(39),       name: "Auffahrt" },
    { datum: ab(50),       name: "Pfingstmontag" },
    { datum: ab(60),       name: "Fronleichnam" },
    { datum: fest(8, 1),   name: "Bundesfeier" },
    { datum: fest(8, 15),  name: "Mariä Himmelfahrt" },
    { datum: fest(11, 1),  name: "Allerheiligen" },
    { datum: fest(12, 8),  name: "Mariä Empfängnis" },
    { datum: fest(12, 25), name: "Weihnachten" },
    { datum: fest(12, 26), name: "Stephanstag" },
  ].sort((a, b) => a.datum.localeCompare(b.datum));
}

function naechsterFeiertag() {
  const heute = isoDatum(new Date());
  const jahr = new Date().getFullYear();
  const alle = feiertage(jahr).concat(feiertage(jahr + 1));
  const kommend = alle.find((f) => f.datum >= heute);
  if (!kommend) return null;

  const tage = Math.round((ausIso(kommend.datum) - ausIso(heute)) / 86400000);
  return { name: kommend.name, datum: kommend.datum, tage: tage };
}

