const WETTER_TEXT = {
  0: "klar", 1: "meist klar", 2: "teils bewölkt", 3: "bewölkt",
  45: "Nebel", 48: "Reifnebel",
  51: "leichter Niesel", 53: "Niesel", 55: "starker Niesel",
  61: "leichter Regen", 63: "Regen", 65: "starker Regen",
  66: "gefrierender Regen", 67: "gefrierender Regen",
  71: "leichter Schneefall", 73: "Schneefall", 75: "starker Schneefall",
  77: "Schneegriesel",
  80: "Regenschauer", 81: "Regenschauer", 82: "kräftige Schauer",
  85: "Schneeschauer", 86: "Schneeschauer",
  95: "Gewitter", 96: "Gewitter mit Hagel", 99: "Gewitter mit Hagel",
};

async function holeWetter() {
  const adresse = "https://api.open-meteo.com/v1/forecast"
    + "?latitude=" + ORT.lat + "&longitude=" + ORT.lon
    + "&current=temperature_2m,weather_code"
    + "&daily=temperature_2m_max,temperature_2m_min"
    + "&timezone=Europe%2FZurich&forecast_days=1";

  const antwort = await zeitlimit(fetch(adresse), 6000, "Wetter");
  if (!antwort.ok) throw new Error("Wetterdienst antwortet nicht");
  const d = await antwort.json();

  return {
    temperatur: Math.round(d.current.temperature_2m),
    text: WETTER_TEXT[d.current.weather_code] || "",
    hoch: Math.round(d.daily.temperature_2m_max[0]),
    tief: Math.round(d.daily.temperature_2m_min[0]),
  };
}

