// =================================================================
//  DOKUMENTE
//  Dateien hängen entweder an einer HOCO Nr. oder an einem
//  Maschinentyp. Welche Art es ist, erkennt die App am Dateinamen.
//  Der Ordnerabgleich liest einen Ordner, ordnet alles zu und lädt
//  es hoch — ohne dass jemand Dateien einzeln auswählen muss.
// =================================================================

const DOK_ARTEN = {
  zeichnung:     { name: "Zeichnung",     zeichen: "📐" },
  wbg:           { name: "WBG",           zeichen: "📋" },
  einrichtblatt: { name: "Einrichtblatt", zeichen: "🔧" },
  sonstiges:     { name: "Allgemein",     zeichen: "📄" },
};

// =================================================================
//  REGELN FÜR DATEINAMEN
//  Welche Stichwörter im Dateinamen wohin führen. Fest im Code, seit
//  die Felder dafür aus den Einstellungen weg sind (Wunsch 5. Oktober
//  2026: „nervt nur“). Dieselbe Liste steht in skripte/dokumente-teile.ps1,
//  Änderungen an beiden Stellen nachziehen. Die Erkennung ist tolerant:
//  Gross und klein egal, Striche und Leerzeichen egal, ein Tippfehler
//  bei längeren Wörtern wird verziehen. Nur die HOCO Nr. im Namen heisst
//  Zeichnung (PDF) oder Einrichtblatt (Excel).
// =================================================================

const DOK_REGELN = {
  zeichnung: ["zeichnung", "zng", "drawing", "zchn"],
  wbg: ["wbg", "werkbegleitschein", "begleitschein"],
  einrichtblatt: ["eb", "einrichtblatt", "einrichteblatt", "einrichten", "setup", "werkzeugprotokoll"],
};

// Nur Buchstaben und Ziffern, klein — "SW-20", "sw 20" und "SW20" sind gleich
function dokGlatt(t) { return String(t || "").toLowerCase().replace(/[^a-z0-9äöü]/g, ""); }

// Unterschied zweier Wörter in Buchstaben (höchstens bis 2 gezählt)
function dokAbstand(a, b) {
  if (Math.abs(a.length - b.length) > 2) return 3;
  const d = Array.from({ length: a.length + 1 }, (u, i) => [i].concat(Array(b.length).fill(0)));
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1,
        d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return d[a.length][b.length];
}

// Kommt ein Stichwort im Namen vor? Kurze Stichwörter (bis 3 Zeichen,
// etwa "EB") müssen als eigenes Wort dastehen, längere dürfen irgendwo
// stecken und einen Buchstaben Unterschied haben.
function dokStichwortPasst(woerter, glattGanz, stichwort) {
  const s = dokGlatt(stichwort);
  if (!s) return false;
  if (s.length <= 3) return woerter.indexOf(s) !== -1;
  if (glattGanz.indexOf(s) !== -1) return true;
  return woerter.some((w) => w.length >= 4 && dokAbstand(w, s) <= 1);
}

// Aus dem Dateinamen lesen, wohin die Datei gehört
function dokErkennen(dateiname, typen) {
  const roh = String(dateiname || "");
  const ohneEndung = roh.replace(/\.[^.]+$/, "");

  // HOCO Nr.: fünf Ziffern, Strich, vier Ziffern (auch mit Leerzeichen am Strich)
  const treffer = ohneEndung.match(/(\d{4,6})\s?-\s?(\d{3,5})/);
  const hoco = treffer ? treffer[1] + "-" + treffer[2] : null;

  const rest = (treffer ? ohneEndung.replace(treffer[0], " ") : ohneEndung);
  const woerter = rest.split(/[^A-Za-z0-9ÄÖÜäöü]+/).map(dokGlatt).filter(Boolean);
  const glattGanz = dokGlatt(rest);

  // Typ: der längste Typname, der im Rest vorkommt
  let typ = null;
  (typen || []).forEach((t) => {
    const n = dokGlatt(t.name);
    if (n.length >= 3 && glattGanz.indexOf(n) !== -1
        && (!typ || n.length > dokGlatt(typ.name).length)) typ = t;
  });
  // Den Typnamen aus den Wörtern nehmen, damit er kein Stichwort vortäuscht
  const ohneTyp = typ ? glattGanz.replace(dokGlatt(typ.name), "") : glattGanz;

  // FA Nr.: eine eigene Zahl mit 7 bis 10 Ziffern neben der HOCO Nr.,
  // etwa „20268566 10007-0381“. Sie steht nur auf WBGs.
  const faTreffer = rest.match(/(?:^|\D)(\d{7,10})(?!\d)/);
  const fa = faTreffer ? faTreffer[1] : null;
  // Einrichtblätter sind immer Excel-Dateien (Wunsch 5. Oktober 2026)
  const istExcel = /\.(xlsx|xlsm|xls)$/i.test(roh);

  let art = null, grund = "";
  for (const k of ["wbg", "einrichtblatt", "zeichnung"]) {
    const sw = DOK_REGELN[k].find((s) => dokStichwortPasst(woerter, ohneTyp, s));
    if (sw) { art = k; grund = "Stichwort „" + sw + "“"; break; }
  }
  // Ein Stichwort für Zeichnung oder WBG passt nicht zu Excel
  if (istExcel && (art === "zeichnung" || art === "wbg")) art = null;
  if (!art && fa && !istExcel) { art = "wbg"; grund = "FA Nr. " + fa + " im Namen"; }
  if (!art && istExcel && (hoco || typ)) { art = "einrichtblatt"; grund = "Excel-Datei"; }
  // Einrichtblätter nur als Excel (Wunsch 5. Oktober 2026): eine PDF mit
  // „EB“ im Namen wird nicht mehr als Einrichtblatt abgelegt
  const nurExcel = art === "einrichtblatt" && !istExcel;
  if (nurExcel) grund = "Einrichtblätter nur als Excel-Datei";
  // Übrig gebliebene Wörter ohne den Typ — ist sonst nichts im Namen?
  const sonstNichts = !ohneTyp.replace(/\d/g, "");
  if (!art) {
    if (hoco && sonstNichts) {
      art = "zeichnung";
      grund = "nur die Nummer im Namen";
    } else {
      // „Allgemein“ gibt es nicht mehr (111.54.0): Was weder Zeichnung,
      // WBG noch Einrichtblatt ist, wird nicht abgelegt
      art = "sonstiges";
      grund = "weder Zeichnung, WBG noch Einrichtblatt im Namen";
    }
  }

  const titel = rest.replace(/[_]+/g, " ").replace(/\s+/g, " ").trim();
  const mitFa = art === "wbg" && fa;
  return {
    dateiname: roh,
    hoco: hoco,
    typ: typ,
    art: art,
    grund: grund,
    fa: mitFa ? fa : null,
    titel: mitFa ? "WBG FA " + fa : (titel || (hoco || ohneEndung)),
    passt: !nurExcel && art !== "sonstiges" && !!(hoco || typ || mitFa),
  };
}

// Offene Aufträge einer HOCO Nr., der nächste zuerst
async function dokOffeneAuftraege(hoco) {
  const r = await db.from("jobs").select("id, job_number, fa_nr, machine_id, planned_from, wbg_url")
    .eq("job_number", hoco).is("ended_at", null);
  if (r.error) throw r.error;
  return (r.data || []).slice().sort((a, b) =>
    String(a.planned_from || "9999").localeCompare(String(b.planned_from || "9999")));
}

// Was sich nur mit der Datenbank klären lässt, vor dem Hochladen:
// - WBG mit FA Nr.: An welchen Auftrag? Die FA Nr. gibt es nur einmal.
//   Steht sie schon auf einem Auftrag, kommt die WBG dorthin (neue
//   Fassung). Sonst an den nächsten offenen Auftrag der HOCO Nr., der
//   noch keine FA Nr. hat, und die FA Nr. wird dort eingetragen.
// - Einrichtblatt mit HOCO Nr., aber ohne Typ im Namen: Typ der
//   Maschine, auf der der nächste offene Auftrag dieser Nummer steht.
async function dokZielSuchen(z, typen) {
  const n = Object.assign({}, z, { geprueft: true });
  try {
    if (n.art === "wbg" && n.fa) {
      const r = await db.from("jobs").select("id, job_number, fa_nr, machine_id, planned_from, wbg_url")
        .eq("fa_nr", n.fa).limit(1);
      let auftrag = (r.data || [])[0] || null;
      if (!auftrag && n.hoco) {
        auftrag = (await dokOffeneAuftraege(n.hoco)).find((j) => !String(j.fa_nr || "").trim()) || null;
      }
      n.auftrag = auftrag;
      if (auftrag) n.hoco = auftrag.job_number || n.hoco;
      n.passt = !!auftrag;
      if (!auftrag) {
        n.grund = n.hoco ? "kein offener Auftrag der HOCO Nr. " + n.hoco + " ohne FA Nr."
          : "kein Auftrag mit der FA Nr. " + n.fa + " und keine HOCO Nr. im Namen";
      }
    }
    if (n.art === "einrichtblatt" && n.hoco && !n.typ) {
      for (const j of await dokOffeneAuftraege(n.hoco)) {
        if (!j.machine_id) continue;
        const m = await db.from("machines").select("type_id").eq("id", j.machine_id).maybeSingle();
        const tid = m && m.data && m.data.type_id;
        const t = tid && ((typen || []).find((x) => String(x.id) === String(tid)) || { id: tid, name: "" });
        if (t) { n.typ = t; n.typAusAuftrag = true; break; }
      }
    }
  } catch (f) {
    if (n.art === "wbg" && n.fa) { n.passt = false; n.grund = fehlertext(f); }
  }
  return n;
}

// Wohin eine Datei geht, in Worten — für die Probe und den Verlauf
function dokZielText(z) {
  const name = (DOK_ARTEN[z.art] || DOK_ARTEN.sonstiges).name;
  if (!z.passt) {
    if (z.fa || z.art === "einrichtblatt" || z.art === "sonstiges") return "nicht zuzuordnen: " + z.grund;
    return "keine HOCO Nr. und kein Typ erkannt";
  }
  if (z.art === "einrichtblatt" && z.typ && !z.hoco) return "Einrichtblatt-Vorlage des Typs " + z.typ.name;
  if (z.art === "wbg" && z.fa) {
    if (z.auftrag) return "WBG mit FA " + z.fa + " an den Auftrag " + z.auftrag.job_number
      + (z.auftrag.planned_from ? " vom " + kurzDatum(z.auftrag.planned_from) : "");
    return "WBG mit FA " + z.fa + " an den nächsten offenen Auftrag"
      + (z.hoco ? " der HOCO Nr. " + z.hoco : "");
  }
  return name + (z.hoco ? " der HOCO Nr. " + z.hoco : "")
    + (z.typ ? " auf dem Typ " + z.typ.name : "");
}

// Pfad in der Ablage aus der öffentlichen Adresse
function ablagePfad(adresse) {
  const m = String(adresse || "").match(/\/object\/public\/zeichnungen\/(.+)$/);
  return m ? decodeURIComponent(m[1].split("?")[0]) : null;
}

// Wird eine Datei noch irgendwo gebraucht? Dann bleibt sie liegen.
async function dateiNochVerwendet(adresse) {
  const pruef = [
    db.from("jobs").select("id").eq("drawing_url", adresse).limit(1),
    db.from("jobs").select("id").eq("wbg_url", adresse).limit(1),
    db.from("hoco_parts").select("hoco_nr").eq("zeichnung_url", adresse).limit(1),
    db.from("dokumente").select("id").eq("datei_url", adresse).limit(1),
    db.from("machine_types").select("id").eq("blatt_url", adresse).limit(1),
    db.from("hoco_type_data").select("hoco_nr").eq("blatt_url", adresse).limit(1),
  ];
  try {
    const r = await Promise.all(pruef);
    return r.some((x) => x && !x.error && x.data && x.data.length);
  } catch (f) { return true; }      // im Zweifel nicht löschen
}

// Alte Dateien aus der Ablage löschen — nur solche, die uns gehören und
// die nirgends mehr gebraucht werden
async function ablageLoeschen(adressen) {
  const frei = [];
  for (const u of [...new Set((adressen || []).filter(Boolean))]) {
    if (!ablagePfad(u)) continue;
    if (await dateiNochVerwendet(u)) continue;
    frei.push(ablagePfad(u));
  }
  if (!frei.length) return;
  try { await db.storage.from("zeichnungen").remove(frei); } catch (f) { /* bleibt eben liegen */ }
}

// Neue Zeichnung am Auftrag: gilt ab jetzt für die ganze HOCO Nr.,
// die alte Datei verschwindet
async function zeichnungErsetzen(hocoNr, neu, alt) {
  const alte = [alt];
  try {
    const t = await db.from("hoco_parts").select("zeichnung_url").eq("hoco_nr", hocoNr).maybeSingle();
    if (t && t.data) {
      alte.push(t.data.zeichnung_url);
      await db.from("hoco_parts").update({ zeichnung_url: neu }).eq("hoco_nr", hocoNr);
    }
    await db.from("jobs").update({ drawing_url: neu }).eq("job_number", hocoNr);
    await db.from("dokumente").delete().eq("art", "zeichnung").eq("hoco_nr", hocoNr).is("type_id", null);
  } catch (f) { /* Hauptsache, der Auftrag hat die neue */ }
  await ablageLoeschen(alte.filter((u) => u && u !== neu));
}

// Zeichnung einer HOCO Nr. entfernen (Wunsch Patrick 8. Oktober 2026):
// Die Aufgabe „HoferTool“ lädt je HOCO Nr. eine Zeichnung aus dem
// Zeichnungs-Ordner hoch. Passt sie nicht, nimmt man sie hier weg, und
// beim nächsten Durchlauf kommt die nächste Datei. Weg aus den
// Stammdaten, von allen Aufträgen der Nummer und aus „Zuletzt
// abgelegt“, mit einer Rückfrage. Die Datei bleibt in der Ablage, damit
// Rückgängig alles zurückholen kann.
async function zeichnungEntfernen(hocoNr) {
  const ok = await nachfragen({ titel: "Zeichnung entfernen",
    text: "Soll die Zeichnung der HOCO Nr. " + hocoNr + " entfernt werden? Liegt im Zeichnungs-Ordner "
      + "noch eine andere Datei zu dieser Nummer, lädt die Aufgabe „HoferTool“ beim nächsten Durchlauf diese hoch.",
    bestaetigen: "Entfernen", gefahr: true });
  if (!ok) return false;
  const teile = await rueckSichern("hoco_parts", { hoco_nr: hocoNr });
  const auftraege = await rueckSichern("jobs", { job_number: hocoNr });
  const doks = await rueckSichern("dokumente", { art: "zeichnung", hoco_nr: hocoNr });
  const r1 = await db.from("hoco_parts").update({ zeichnung_url: null }).eq("hoco_nr", hocoNr);
  if (r1.error) throw r1.error;
  const r2 = await db.from("jobs").update({ drawing_url: null }).eq("job_number", hocoNr);
  if (r2.error) throw r2.error;
  try { await db.from("dokumente").delete().eq("art", "zeichnung").eq("hoco_nr", hocoNr); } catch (f) { /* dann bleibt der Eintrag */ }
  merkeSchritt("Zeichnung " + hocoNr + " entfernt",
    teile.filter((t) => t.zeichnung_url).map((t) => rueckSetz("hoco_parts", { zeichnung_url: t.zeichnung_url }, { hoco_nr: t.hoco_nr }))
      .concat(auftraege.filter((j) => j.drawing_url).map((j) => rueckSetz("jobs", { drawing_url: j.drawing_url }, { id: j.id })))
      .concat(doks.length ? [rueckRein("dokumente", doks)] : []));
  dokVerlauf({ art: "zeichnung", hoco_nr: hocoNr, ziel: "Zeichnung entfernt", quelle: "hand" });
  return true;
}

// WBG eines Auftrags entfernen (Wunsch Patrick, 9. Oktober 2026: „WBGs
// und Einrichtblätter kann jeder löschen, wie bei der Zeichnung“). Die
// FA Nr. bleibt am Auftrag: Kommt im Pool eine neue WBG mit dieser
// Nummer, hängt dokumente-pool.ps1 sie wieder an. Mit Rückgängig.
async function wbgEntfernen(auftragId) {
  const j = await rueckSichern("jobs", { id: auftragId });
  const auftrag = j[0];
  if (!auftrag || !auftrag.wbg_url) return false;
  const ok = await nachfragen({ titel: "WBG entfernen",
    text: "Soll die WBG" + (auftrag.fa_nr ? " mit FA " + auftrag.fa_nr : "") + " vom Auftrag " + (auftrag.job_number || "")
      + " entfernt werden? Legt jemand eine neue WBG in den Pool-Ordner, hängt die Aufgabe „HoferTool“ sie wieder an.",
    bestaetigen: "Entfernen", gefahr: true });
  if (!ok) return false;
  const doks = await rueckSichern("dokumente", { art: "wbg", datei_url: auftrag.wbg_url });
  const r = await db.from("jobs").update({ wbg_url: null }).eq("id", auftragId);
  if (r.error) throw r.error;
  try { if (doks.length) await db.from("dokumente").delete().in("id", doks.map((d) => d.id)); } catch (f) { /* dann bleibt der Eintrag */ }
  merkeSchritt("WBG " + (auftrag.fa_nr || auftrag.job_number || "") + " entfernt",
    [rueckSetz("jobs", { wbg_url: auftrag.wbg_url }, { id: auftragId })].concat(doks.length ? [rueckRein("dokumente", doks)] : []));
  dokVerlauf({ art: "wbg", hoco_nr: auftrag.job_number || null, ziel: "WBG entfernt" + (auftrag.fa_nr ? " (FA " + auftrag.fa_nr + ")" : ""), quelle: "hand" });
  return true;
}

// Einrichtblatt einer HOCO Nr. auf einem Typ entfernen. Liegt im
// Typ-Ordner noch eine andere Excel-Datei zu dieser Nummer, lädt
// einrichtblaetter.ps1 beim nächsten Durchlauf diese hoch; die
// entfernte kommt nie wieder. Mit Rückgängig.
async function einrichtblattEntfernen(hocoNr, typId) {
  const zeilen = await rueckSichern("hoco_type_data", { hoco_nr: hocoNr, type_id: typId });
  const z = zeilen[0];
  if (!z || !z.blatt_url) return false;
  const ok = await nachfragen({ titel: "Einrichtblatt entfernen",
    text: "Soll das Einrichtblatt der HOCO Nr. " + hocoNr + " auf diesem Typ entfernt werden? Liegt im Einrichtblatt-Ordner "
      + "noch eine andere Excel-Datei zu dieser Nummer, lädt die Aufgabe „HoferTool“ beim nächsten Durchlauf diese hoch.",
    bestaetigen: "Entfernen", gefahr: true });
  if (!ok) return false;
  const doks = await rueckSichern("dokumente", { art: "einrichtblatt", hoco_nr: hocoNr, type_id: typId });
  const r = await db.from("hoco_type_data").update({ blatt_url: null }).eq("hoco_nr", hocoNr).eq("type_id", typId);
  if (r.error) throw r.error;
  try { if (doks.length) await db.from("dokumente").delete().in("id", doks.map((d) => d.id)); } catch (f) { /* dann bleibt der Eintrag */ }
  merkeSchritt("Einrichtblatt " + hocoNr + " entfernt",
    [rueckSetz("hoco_type_data", { blatt_url: z.blatt_url }, { hoco_nr: hocoNr, type_id: typId })]
      .concat(doks.length ? [rueckRein("dokumente", doks)] : []));
  dokVerlauf({ art: "einrichtblatt", hoco_nr: hocoNr, type_id: typId, ziel: "Einrichtblatt entfernt", quelle: "hand" });
  return true;
}

// Ein Eintrag im Verlauf: welche Datei wohin ging
async function dokVerlauf(eintrag) {
  try {
    await db.from("dokumente_verlauf").insert([Object.assign({
      dateiname: null, art: null, hoco_nr: null, type_id: null, ziel: null,
      quelle: "hand", ersetzt: false }, eintrag)]);
  } catch (f) { /* ohne Verlauf geht es auch */ }
}

// Eine Datei hochladen und dort ablegen, wo sie hingehört. Was an
// derselben Stelle schon lag, wird ersetzt: der alte Eintrag und die
// alte Datei verschwinden.
async function dokHochladen(datei, zuordnung, quelle) {
  // Ziel erst klären, damit nichts hochgeladen wird, das nirgends hingehört
  if (!zuordnung.geprueft && ((zuordnung.art === "wbg" && zuordnung.fa)
      || (zuordnung.art === "einrichtblatt" && zuordnung.hoco && !zuordnung.typ))) {
    zuordnung = await dokZielSuchen(zuordnung, (typeof prod !== "undefined" && prod.typen) || []);
  }
  if (zuordnung.art === "einrichtblatt" && !istExcelDatei(datei.name)) {
    throw new Error("Einrichtblätter nur als Excel-Datei (.xlsx, .xlsm, .xls).");
  }
  if (zuordnung.art === "wbg" && zuordnung.fa && !zuordnung.auftrag) {
    throw new Error("Nicht zuzuordnen: " + (zuordnung.grund || "kein passender Auftrag"));
  }
  const endung = (datei.name.split(".").pop() || "pdf").toLowerCase();
  const name = "dok/" + Date.now() + "-"
    + Math.random().toString(36).slice(2, 8) + "." + endung;

  const hoch = await db.storage.from("zeichnungen")
    .upload(name, datei, { upsert: true, contentType: datei.type || undefined });
  if (hoch.error) throw hoch.error;
  const adresse = db.storage.from("zeichnungen").getPublicUrl(name).data.publicUrl;

  const art = zuordnung.art || "sonstiges";
  const hocoNr = zuordnung.hoco || null;
  const typId = zuordnung.typ ? zuordnung.typ.id : null;
  const titel = zuordnung.titel || datei.name.replace(/\.[^.]+$/, "");

  // Was an derselben Stelle liegt: gleiche Nummer, gleicher Typ, gleiche
  // Art — bei allgemeinen Dokumenten zusätzlich derselbe Titel
  const alte = [];
  try {
    let a = db.from("dokumente").select("id, datei_url, titel").eq("art", art);
    a = hocoNr ? a.eq("hoco_nr", hocoNr) : a.is("hoco_nr", null);
    a = typId ? a.eq("type_id", typId) : a.is("type_id", null);
    const r = await a;
    ((r && r.data) || []).forEach((d) => {
      // Allgemeines und WBG mit FA Nr. (je Auftrag eine) nur bei gleichem Titel
      const nachTitel = art === "sonstiges" || (art === "wbg" && zuordnung.fa);
      if (!nachTitel || dokGlatt(d.titel) === dokGlatt(titel)) alte.push(d);
    });
  } catch (f) { /* dann eben ohne Ersetzen */ }

  const satz = { art: art, hoco_nr: hocoNr, type_id: typId, titel: titel,
                 dateiname: datei.name, datei_url: adresse, groesse: datei.size || null };
  if (alte.length) {
    await db.from("dokumente").delete().in("id", alte.map((d) => d.id));
  }
  const ein = await db.from("dokumente").insert(satz);
  if (ein.error) throw ein.error;

  // Dort eintragen, wo die App sie im Alltag erwartet — und die alte
  // Datei an derselben Stelle ersetzen
  const alteAdressen = alte.map((d) => d.datei_url);
  try {
    if (art === "zeichnung" && hocoNr) {
      const t = await db.from("hoco_parts").select("zeichnung_url").eq("hoco_nr", hocoNr).maybeSingle();
      if (t && t.data && t.data.zeichnung_url) alteAdressen.push(t.data.zeichnung_url);
      await db.from("hoco_parts").update({ zeichnung_url: adresse }).eq("hoco_nr", hocoNr);
      // Alle Aufträge dieser Nummer zeigen ab jetzt die neue Zeichnung
      await db.from("jobs").update({ drawing_url: adresse }).eq("job_number", hocoNr);
    }
    if (art === "einrichtblatt" && typId && !hocoNr) {
      const t = await db.from("machine_types").select("blatt_url").eq("id", typId).maybeSingle();
      if (t && t.data && t.data.blatt_url) alteAdressen.push(t.data.blatt_url);
      await db.from("machine_types").update({ blatt_url: adresse }).eq("id", typId);
    }
    if (art === "einrichtblatt" && typId && hocoNr) {
      const t = await db.from("hoco_type_data").select("blatt_url")
        .eq("hoco_nr", hocoNr).eq("type_id", typId).maybeSingle();
      if (t && t.data && t.data.blatt_url) alteAdressen.push(t.data.blatt_url);
      await db.from("hoco_type_data").upsert(
        { hoco_nr: hocoNr, type_id: typId, blatt_url: adresse }, { onConflict: "hoco_nr,type_id" });
    }
    if (art === "wbg" && zuordnung.fa && zuordnung.auftrag) {
      // Nur dieser eine Auftrag bekommt WBG und FA Nr.
      const j = zuordnung.auftrag;
      if (j.wbg_url) alteAdressen.push(j.wbg_url);
      const r = await db.from("jobs").update({ wbg_url: adresse, fa_nr: zuordnung.fa }).eq("id", j.id);
      if (r && r.error) throw r.error;
    } else if (art === "wbg" && hocoNr) {
      // Die WBG gehört zu den offenen Aufträgen dieser Nummer
      const o = await db.from("jobs").select("id, wbg_url").eq("job_number", hocoNr).is("ended_at", null);
      ((o && o.data) || []).forEach((j) => { if (j.wbg_url) alteAdressen.push(j.wbg_url); });
      await db.from("jobs").update({ wbg_url: adresse }).eq("job_number", hocoNr).is("ended_at", null);
    }
  } catch (f) { /* Hauptsache, der Eintrag steht */ }

  // Alte Dateien wegräumen — aber nie die, die gerade hochgeladen wurde
  await ablageLoeschen(alteAdressen.filter((u) => u && u !== adresse));

  await dokVerlauf({ dateiname: datei.name, art: art, hoco_nr: hocoNr, type_id: typId,
                     ziel: dokZielText(zuordnung), quelle: quelle || "hand",
                     ersetzt: alteAdressen.length > 0 });
  return adresse;
}

// =================================================================
//  WBG AUFRÄUMEN
//  Eine WBG bleibt, solange ihr Auftrag läuft, und noch fünf Tage
//  danach. Dann verschwinden Datei und Eintrag. Läuft einmal am Tag,
//  sobald jemand mit Schreibrecht die App öffnet.
// =================================================================

async function wbgAufraeumen(sofort) {
  if (!profil || !(istAdmin() || darfSchreiben())) return 0;
  const heute = isoDatum(new Date());
  try {
    if (!sofort && localStorage.getItem("hofer.wbgaufgeraeumt") === heute) return 0;
    localStorage.setItem("hofer.wbgaufgeraeumt", heute);
  } catch (f) { /* dann eben jedes Mal */ }

  const grenze = new Date(Date.now() - 5 * 86400000).toISOString();
  let weg = 0;
  try {
    // 1. WBG an Aufträgen, die seit mehr als fünf Tagen beendet sind
    const r = await db.from("jobs").select("id, job_number, wbg_url")
      .not("wbg_url", "is", null).lt("ended_at", grenze).limit(500);
    const alt = (r && r.data) || [];
    if (alt.length) {
      // Dieselbe Datei hängt vielleicht noch an einem offenen Auftrag
      const noch = await db.from("jobs").select("wbg_url").is("ended_at", null).not("wbg_url", "is", null);
      const inBenutzung = new Set(((noch && noch.data) || []).map((j) => j.wbg_url));
      // Adressen vorher festhalten, danach stehen sie nicht mehr am Auftrag
      const adressen = alt.map((j) => j.wbg_url).filter((u) => !inBenutzung.has(u));
      await db.from("jobs").update({ wbg_url: null }).in("id", alt.map((j) => j.id));
      await ablageLoeschen(adressen);
      weg += alt.length;
    }
    // 2. WBG in den Dokumenten, zu denen kein offener Auftrag mehr läuft
    const d = await db.from("dokumente").select("id, hoco_nr, datei_url, erstellt_am").eq("art", "wbg");
    const liste = (d && d.data) || [];
    for (const w of liste) {
      if (!w.hoco_nr) continue;
      const offen = await db.from("jobs").select("id").eq("job_number", w.hoco_nr).is("ended_at", null).limit(1);
      if (offen && offen.data && offen.data.length) continue;
      const zuletzt = await db.from("jobs").select("ended_at").eq("job_number", w.hoco_nr)
        .not("ended_at", "is", null).order("ended_at", { ascending: false }).limit(1);
      const ende = zuletzt && zuletzt.data && zuletzt.data[0] ? zuletzt.data[0].ended_at : w.erstellt_am;
      if (ende && ende < grenze) {
        await db.from("dokumente").delete().eq("id", w.id);
        await ablageLoeschen([w.datei_url]);
        await dokVerlauf({ dateiname: null, art: "wbg", hoco_nr: w.hoco_nr,
                           ziel: "WBG entfernt — Auftrag seit über fünf Tagen beendet",
                           quelle: "aufräumen" });
        weg++;
      }
    }
  } catch (f) { fehlerMerken("WBG aufräumen", fehlertext(f)); }
  return weg;
}

// Dokumente zu einer HOCO Nr. oder einem Typ holen
async function dokListe({ hoco, typId }) {
  try {
    let a = db.from("dokumente").select("*").order("erstellt_am", { ascending: false });
    if (hoco) a = a.eq("hoco_nr", hoco);
    if (typId) a = a.eq("type_id", typId);
    const r = await a;
    if (r.error) throw r.error;
    return r.data || [];
  } catch (f) { return []; }
}

async function dokLoeschen(id) {
  const r = await db.from("dokumente").delete().eq("id", id);
  if (r.error) throw r.error;
}

// Dateien auswählen und hochladen — für einzelne Nachträge
function dokWaehlen(mehrere) {
  return new Promise((fertig) => {
    const feld = document.createElement("input");
    feld.type = "file";
    feld.accept = "application/pdf,image/*,.xlsx,.xlsm,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel";
    if (mehrere) feld.multiple = true;
    feld.onchange = () => fertig([...(feld.files || [])]);
    feld.click();
  });
}

// ---------- Notizen ----------

async function ladeTodos() {
  const { data, error } = await zeitlimit(
    db.from("todos").select("*, profiles!todos_created_by_fkey(full_name, email)").eq("is_done", false)
      .order("due_date", { ascending: true, nullsFirst: false })
      .order("created_at").limit(20),
    8000, "Notizen");
  if (error) throw error;
  return data || [];
}

// ---------- Seite ----------



// =================================================================
//  SOLARANLAGE
//  Zeigt, was die Anlage gerade erzeugt, was der Betrieb zieht und
//  ob gerade eingespeist oder bezogen wird. Die Werte kommen aus
//  der Tabelle solar_werte, gefüllt von aussen.
// =================================================================

// Welche Spanne der Verlauf zeigt: Tag, Woche oder Monat
let solarSpanne = "tag";

// Längere Spannen: alle Messwerte holen, blockweise, und zu Stunden-
// oder Tagesmitteln verdichten — sonst wird die Kurve unlesbar und
// die Seite langsam.
async function solarVerlaufLaden(spanne) {
  const tage = spanne === "monat" ? 30 : 7;
  const seit = new Date(Date.now() - tage * 24 * 3600 * 1000).toISOString();
  const alle = [];
  for (let von = 0; von < 60000; von += 1000) {
    const { data, error } = await zeitlimit(
      db.from("solar_werte").select("gemessen, produktion_w, verbrauch_w")
        .gte("gemessen", seit).order("gemessen", { ascending: true })
        .range(von, von + 999),
      12000, "Solarverlauf");
    if (error) throw error;
    alle.push(...(data || []));
    if (!data || data.length < 1000) break;
  }
  const schritt = spanne === "monat" ? 24 * 3600 * 1000 : 3600 * 1000;
  const eimer = new Map();
  alle.forEach((x) => {
    const t = new Date(x.gemessen).getTime();
    const k = Math.floor(t / schritt) * schritt;
    const e = eimer.get(k) || { n: 0, p: 0, v: 0 };
    e.n += 1; e.p += Number(x.produktion_w) || 0; e.v += Number(x.verbrauch_w) || 0;
    eimer.set(k, e);
  });
  return [...eimer.entries()].sort((a, b) => a[0] - b[0]).map(([k, e]) => ({
    gemessen: new Date(k + schritt / 2).toISOString(),
    produktion_w: e.p / e.n, verbrauch_w: e.v / e.n,
  }));
}

async function solarLaden() {
  const seit = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
  const { data, error } = await zeitlimit(
    db.from("solar_werte").select("*").gte("gemessen", seit)
      .order("gemessen", { ascending: true }).limit(600),
    10000, "Solarwerte");
  if (error) throw error;
  return data || [];
}

function solarKw(w) {
  const z = Number(w) || 0;
  if (Math.abs(z) >= 1000) return (z / 1000).toFixed(2).replace(".", ",") + " kW";
  return Math.round(z) + " W";
}

// Der Fluss: Anlage → Betrieb → Netz. Die Linien sind bewegt, die
// Geschwindigkeit richtet sich nach der Leistung — man sieht auf
// einen Blick, wo gerade viel unterwegs ist.
function solarFluss(j) {
  const prod = Number(j.produktion_w) || 0;
  const verb = Number(j.verbrauch_w) || 0;
  const netz = Number(j.netz_w) || 0;
  const bezug = netz > 0;
  const eigen = Math.max(0, Math.min(prod, verb));
  const anteil = verb > 0 ? Math.round((eigen / verb) * 100) : 0;
  const gross = Math.max(1, prod, verb, Math.abs(netz));

  // Je mehr Leistung, desto schneller läuft die Linie
  const tempo = (w) => (6 - (Math.abs(w) / gross) * 4.4).toFixed(2) + "s";
  const dick = (w) => (2.5 + (Math.abs(w) / gross) * 4).toFixed(1);

  const ring = 2 * Math.PI * 34;
  const gefuellt = (ring * Math.min(100, anteil)) / 100;

  return '<div class="sol">'
    + '<div class="sol__karten">'

    // Erzeugung
    + '<div class="sol-kachel sol-kachel--sonne">'
    + '<svg viewBox="0 0 24 24" class="sol-sym"><circle cx="12" cy="12" r="5"/>'
    + '<path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1'
    + 'M17 7l2.1-2.1M4.9 19.1L7 17" stroke-linecap="round"/></svg>'
    + '<span class="sol-kachel__name">Erzeugung</span>'
    + '<span class="sol-kachel__wert">' + solarKw(prod) + '</span>'
    + '</div>'

    // Verbrauch
    + '<div class="sol-kachel sol-kachel--haus">'
    + '<svg viewBox="0 0 24 24" class="sol-sym">'
    + '<path d="M3 11l9-7 9 7v9a1 1 0 01-1 1H4a1 1 0 01-1-1z"/>'
    + '<path d="M9 21v-6h6v6"/></svg>'
    + '<span class="sol-kachel__name">Verbrauch</span>'
    + '<span class="sol-kachel__wert">' + solarKw(verb) + '</span>'
    + '</div>'

    // Netz
    + '<div class="sol-kachel ' + (bezug ? "sol-kachel--bezug" : "sol-kachel--speisung")
    + '">'
    + '<svg viewBox="0 0 24 24" class="sol-sym">'
    + (bezug
        ? '<path d="M13 2L4 14h6l-1 8 9-12h-6z" stroke-linejoin="round"/>'
        : '<path d="M12 21V8M12 3v2M7 8h10M8 12h8M9 16h6" stroke-linecap="round"/>')
    + '</svg>'
    + '<span class="sol-kachel__name">' + (bezug ? "Netzbezug" : "Einspeisung") + '</span>'
    + '<span class="sol-kachel__wert">' + solarKw(Math.abs(netz)) + '</span>'
    + '</div>'
    + '</div>'

    // Die Verbindungen dazwischen
    + '<svg viewBox="0 0 440 60" class="sol-fluss" preserveAspectRatio="none">'
    + (eigen > 1
        ? '<path d="M78 30H210" class="sol-linie sol-linie--sonne" stroke-width="'
          + dick(eigen) + '" style="--tempo:' + tempo(eigen) + '"/>' : "")
    + (Math.abs(netz) > 1
        ? (bezug
            ? '<path d="M362 30H230" class="sol-linie sol-linie--bezug" stroke-width="'
              + dick(netz) + '" style="--tempo:' + tempo(netz) + '"/>'
            : '<path d="M230 30H362" class="sol-linie sol-linie--speisung" stroke-width="'
              + dick(netz) + '" style="--tempo:' + tempo(netz) + '"/>')
        : "")
    + '</svg>'

    // Eigenverbrauch als Ring
    + '<div class="sol-ring">'
    + '<svg viewBox="0 0 80 80">'
    + '<circle cx="40" cy="40" r="34" class="sol-ring__spur"/>'
    + '<circle cx="40" cy="40" r="34" class="sol-ring__voll"'
    + ' stroke-dasharray="' + gefuellt.toFixed(1) + ' ' + ring.toFixed(1) + '"/>'
    + '</svg>'
    + '<div class="sol-ring__mitte"><span class="sol-ring__zahl">' + anteil
    + '<small>%</small></span></div>'
    + '</div>'
    + '<p class="sol-ring__text">vom Dach gedeckt</p>'
    + '</div>';
}

// Verlauf des Tages als Flächengrafik: Erzeugung gefüllt, Verbrauch
// als Linie darüber. Gezeichnet wird als SVG, ohne fremde Bibliothek.
function solarVerlauf(reihe) {
  const punkte = (reihe || []).filter((x) => x && x.gemessen);
  if (punkte.length < 2) return "";

  const B = 600, H = 120;                       // Zeichenfläche
  const zeit = (x) => new Date(x.gemessen).getTime();
  const t0 = zeit(punkte[0]), t1 = zeit(punkte[punkte.length - 1]);
  const spanne = Math.max(1, t1 - t0);
  const gross = Math.max(1000,
    ...punkte.map((x) => Math.max(Number(x.produktion_w) || 0, Number(x.verbrauch_w) || 0)));

  const x = (p) => ((zeit(p) - t0) / spanne) * B;
  const y = (w) => H - ((Number(w) || 0) / gross) * (H - 6) - 3;

  const linie = (feld) => punkte
    .map((p, i) => (i ? "L" : "M") + x(p).toFixed(1) + " " + y(p[feld]).toFixed(1))
    .join(" ");

  const flaeche = linie("produktion_w")
    + " L" + B + " " + H + " L0 " + H + " Z";

  // Stundenraster, damit man die Tageszeit einordnen kann
  const striche = [];
  for (let k = 1; k < 6; k++) {
    const px = (B / 6) * k;
    striche.push('<line x1="' + px + '" y1="0" x2="' + px + '" y2="' + H
      + '" class="sol-gitter"/>');
  }

  // Beschriftung passend zur Spanne: Uhrzeit am Tag, Datum sonst
  const langeSpanne = spanne > 30 * 3600 * 1000;
  const vonU = langeSpanne ? kurzDatum(isoDatum(new Date(punkte[0].gemessen)))
    : uhrzeit(punkte[0].gemessen);
  const bisU = langeSpanne ? kurzDatum(isoDatum(new Date(punkte[punkte.length - 1].gemessen)))
    : uhrzeit(punkte[punkte.length - 1].gemessen);

  return '<div class="sol-verlauf">'
    + '<svg viewBox="0 0 ' + B + ' ' + H + '" preserveAspectRatio="none">'
    + '<defs><linearGradient id="solFuellung" x1="0" y1="0" x2="0" y2="1">'
    + '<stop offset="0%" stop-color="#c6f135" stop-opacity=".55"/>'
    + '<stop offset="100%" stop-color="#c6f135" stop-opacity="0"/>'
    + '</linearGradient></defs>'
    + striche.join("")
    + '<path d="' + flaeche + '" class="sol-flaeche"/>'
    + '<path d="' + linie("produktion_w") + '" class="sol-kurve sol-kurve--prod"/>'
    + '<path d="' + linie("verbrauch_w") + '" class="sol-kurve sol-kurve--verb"/>'
    + '</svg>'
    + '<div class="sol-verlauf__achse"><span>' + esc(vonU) + '</span>'
    + '<span class="sol-verlauf__mitte">'
    + '<span class="sol-spanne">'
    + [["tag", "Tag"], ["woche", "Woche"], ["monat", "Monat"]].map(([w, t]) =>
        '<button type="button" class="sol-spanne__knopf'
        + ((solarSpanne || "tag") === w ? " aktiv" : "") + '" data-solspanne="' + w + '">'
        + t + '</button>').join("")
    + '</span></span>'
    + '<span>' + esc(bisU) + '</span></div>'
    + '</div>';
}

function uhrzeit(iso) {
  try {
    return new Date(iso).toLocaleTimeString("de-CH",
      { hour: "2-digit", minute: "2-digit" });
  } catch (f) { return ""; }
}

async function solarKachel(ziel) {
  let reihe = [];
  try { reihe = await solarLaden(); }
  catch (f) {
    // Genau sagen, woran es liegt — sonst sucht man im Dunkeln
    const text = fehlertext(f);
    ziel.innerHTML = '<section class="karte"><h2>Solaranlage</h2>'
      + '<p class="hinweis">' + esc(text) + '</p>'
      + '<p class="klein">'
      + (/relation|does not exist|schema cache/i.test(text)
          ? "Die Tabelle solar_werte fehlt. Bitte solar.sql im SQL-Editor ausführen."
          : (/permission|policy|row-level/i.test(text)
              ? "Die Leseregel greift nicht. In solar.sql steht die Regel dafür — "
                + "bitte die Datei noch einmal ausführen."
              : "Falls das SQL schon gelaufen ist, schick mir diese Meldung."))
      + '</p></section>';
    return;
  }

  if (!reihe.length) {
    ziel.innerHTML = '<section class="karte"><h2>Solaranlage</h2>'
      + '<p class="hinweis">Noch keine Werte eingetroffen. Sobald etwas in die '
      + 'Tabelle geschrieben wird, erscheint hier die Anzeige.</p></section>';
    return;
  }

  const j = reihe[reihe.length - 1];
  const sek = Math.round((Date.now() - new Date(j.gemessen).getTime()) / 1000);
  const alt = Math.round(sek / 60);

  const prod = Number(j.produktion_w) || 0;
  const verb = Number(j.verbrauch_w) || 0;
  const netz = Number(j.netz_w) || 0;
  const bezug = netz > 0;
  const eigen = Math.max(0, Math.min(prod, verb));
  const anteil = verb > 0 ? Math.round((eigen / verb) * 100) : 0;
  const ring = 2 * Math.PI * 26;
  const gefuellt = (ring * Math.min(100, anteil)) / 100;

  const zahl = (wert, name, art) => '<div class="sol-zahl sol-zahl--' + art + '">'
    + '<span class="sol-zahl__name">' + name + '</span>'
    + '<span class="sol-zahl__wert">' + solarKw(wert) + '</span></div>';

  ladeFertig(ziel);
  ziel.innerHTML = '<section class="karte solar solar--schmal">'
    + '<div class="sol-kopf">'
    + '<span class="sol-kopf__titel">Solaranlage</span>'
    + '<span class="sol-kopf__stand">' + (alt < 2 ? "live" : "vor " + alt + " Min.") + '</span>'
    + '</div>'

    // Werte und Eigenverbrauch in einer Zeile
    + '<div class="sol-reihe">'
    + zahl(prod, "Erzeugung", "prod")
    + zahl(verb, "Verbrauch", "verb")
    + zahl(Math.abs(netz), bezug ? "Netzbezug" : "Einspeisung", bezug ? "bezug" : "speisung")
    + '<div class="sol-ring sol-ring--klein">'
    + '<svg viewBox="0 0 64 64">'
    + '<circle cx="32" cy="32" r="26" class="sol-ring__spur"/>'
    + '<circle cx="32" cy="32" r="26" class="sol-ring__voll"'
    + ' stroke-dasharray="' + gefuellt.toFixed(1) + ' ' + ring.toFixed(1) + '"/>'
    + '</svg>'
    + '<div class="sol-ring__mitte"><span class="sol-ring__zahl">' + anteil
    + '<small>%</small></span></div>'
    + '<span class="sol-ring__unten">Eigen</span>'
    + '</div>'
    + '</div>'

    + '<div id="sol-verlauf-platz">' + solarVerlauf(reihe) + '</div>'

    + '<div class="solar-tag">'
    + (j.ertrag_tag_kwh !== null && j.ertrag_tag_kwh !== undefined
        ? '<div><span>Ertrag heute</span>'
          + Number(j.ertrag_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + (j.eingespeist_tag_kwh !== null && j.eingespeist_tag_kwh !== undefined
        ? '<div><span>Eingespeist</span>'
          + Number(j.eingespeist_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + (j.bezug_tag_kwh !== null && j.bezug_tag_kwh !== undefined
        ? '<div><span>Bezogen</span>'
          + Number(j.bezug_tag_kwh).toFixed(1).replace(".", ",") + ' kWh</div>' : "")
    + '</div>'
    + '</section>';

  solarSpanneBinden(ziel, reihe);
}

// Umschalten zwischen Tag, Woche und Monat — nur der Verlauf wird
// neu gezeichnet, nicht die ganze Kachel
function solarSpanneBinden(ziel, reiheTag) {
  ziel.querySelectorAll("[data-solspanne]").forEach((el) => {
    el.onclick = async () => {
      solarSpanne = el.dataset.solspanne;
      const platz = ziel.querySelector("#sol-verlauf-platz");
      if (!platz) return;
      let reihe = reiheTag;
      if (solarSpanne !== "tag") {
        platz.classList.add("sol-laedt");
        try { reihe = await solarVerlaufLaden(solarSpanne); }
        catch (f) { meldung(fehlertext(f), "fehler"); platz.classList.remove("sol-laedt"); return; }
      }
      platz.innerHTML = solarVerlauf(reihe);
      platz.classList.remove("sol-laedt");
      solarSpanneBinden(ziel, reiheTag);
    };
  });
}

