// Auf welche Maschinenparks hat der angemeldete Benutzer Zugriff?
// Leere Liste heisst: alle.
function meineParks() {
  return (profil && Array.isArray(profil.parks)) ? profil.parks : [];
}

// Externe Partner sehen nur Parks, die ihnen zugewiesen sind — ohne
// Zuweisung die Parks mit "extern", "Lohn" oder "fremd" im Namen
function istExtern() { return meineRolle() === "extern"; }

// Ferien darf jeder eintragen, verschieben und löschen, ausser Externen
// und dem Dienstkonto (Wunsch Patrick, 9. Oktober 2026). Ziehen und
// Griffe nur am Computer, auf dem Handy über das Ferienfenster.
function darfFerien() {
  const r = meineRolle();
  return !!r && r !== "extern" && r !== "dienst";
}

function parkErlaubt(parkId) {
  if (istAdmin() || meineRolle() === "planwand") return true;
  if (istExtern()) {
    const zu = meineParks();
    if (zu.length) return zu.indexOf(parkId) !== -1;
    const park = (prod.parks || []).concat(plan.parksAlle || []).find((p) => p.id === parkId);
    return /extern|lohn|fremd/i.test(String((park && park.name) || ""));
  }

  // Ausdrücklich zugewiesene Parks haben Vorrang
  const zugewiesen = meineParks();
  if (zugewiesen.length) return zugewiesen.indexOf(parkId) !== -1;

  // Sonst entscheidet der Name des Parks zur Rolle
  const park = (prod.parks || []).concat(plan.parksAlle || [])
    .find((p) => p.id === parkId);
  const name = ((park && park.name) || "").toLowerCase();
  const r = meineRolle();
  if (r === "kurzdreher") return name.includes("kurz");
  if (r === "langdreher") return name.includes("lang");
  return true;
}

function meineRolle() { return (profil && profil.role) || "produktion"; }
function istAdmin() { return meineRolle() === "admin"; }

// „Andere Nutzer“ sind Gerätekonten wie Planwand, Pad Mode oder Päckli
// Pad (Häkchen unter Einstellungen → Nutzer, profiles.andere_nutzer).
// Solche Konten werden nie von selbst abgemeldet (Wunsch Patrick,
// 8. Oktober 2026): keine Abmeldung nach fünf Minuten Ruhe, und die
// Sitzung bleibt auf dem Gerät, auch wenn das Fenster zugeht.
// Ohne u gilt die angemeldete Person. Solange sql/andere-nutzer.sql
// fehlt, kennt das Profil das Häkchen nicht; dann zählt die Rolle
// Planwand, denn genau das waren bisher die Gerätekonten.
function istAndererNutzer(u) {
  const k = u || profil;
  if (!k) return false;
  return k.andere_nutzer === undefined || k.andere_nutzer === null ? k.role === "planwand" : !!k.andere_nutzer;
}
function darfSchreiben() {
  const r = meineRolle();
  return r === "admin" || r === "planwand"
    || r === "langdreher" || r === "kurzdreher";
}

// Seit 111.124.0 dazu Fehlerprotokoll, Farben und Material, Symbole und
// der Text der Bestellmail („Planwand soll bei Einstellungen alles
// machen können wie Admin“); Nutzer, PINs und Passwörter bleiben bei Admins.
// Dokumente und Sicherung: Einstellungen → Dokumente (Ordner am
// Pool-Rechner, Dateien hochladen) und Einstellungen → Backup (Ordner
// wählen, Jetzt sichern, tägliche Sicherung, Zurückspielen) dürfen
// Admins und das Konto Planwand (Wunsch Patrick, 9. Oktober 2026: „die
// Planwand-Rolle soll Zugriff haben mit allem, was mit Dokumente
// hochladen und Backup zu tun hat“). Die Aufgabe „HoferTool“ am
// Pool-Rechner läuft mit dem Dienstkonto, nicht mit Planwand.
// In der Datenbank: sql/planwand-dokumente-sicherung.sql.
function darfDokumenteUndSicherung() {
  return istAdmin() || meineRolle() === "planwand";
}

// Mitarbeiter dürfen überall zusehen, aber nur im Einkauf mitmachen.
function darfEinkaufen() {
  return darfSchreiben() || meineRolle() === "mitarbeiter";
}

