// Bezeichnung aus der Liste wählen oder eine neue anlegen
async function bezeichnungWaehlen(liste, aktuell) {
  const wahl = await auswahlSuchen("Bezeichnung wählen",
    (liste || []).map((z) => ({ wert: z.name, text: z.name }))
      .concat([{ wert: "__neu", text: "+ Neue Bezeichnung anlegen" }]));
  if (!wahl) return null;

  if (wahl !== "__neu") return wahl;

  const w = await dialogFelder({ titel: "Neue Bezeichnung",
    felder: [{ name: "name", label: "Bezeichnung", pflicht: true,
               wert: aktuell || "" }], bestaetigen: "Anlegen" });
  if (!w) return null;

  const { error } = await db.from("designations").insert({ name: w.name });
  if (error && !String(error.message || "").includes("duplicate")) {
    meldung(fehlertext(error), "fehler");
    return null;
  }
  meldung("Bezeichnung angelegt.");
  return w.name;
}

