// Legt einen Artikel mit den nötigsten Angaben an und gibt ihn zurück.
// lieferantVorgabe: ist der Lieferant schon gewählt — etwa im
// Einrichtblatt, wo man zuerst den Hersteller aussucht —, wird er
// nicht noch einmal abgefragt.
async function artikelSchnellAnlegen(vorgabe, lieferantVorgabe) {
  let lieferanten = [], bezeichnungen = [];
  try { lieferanten = await ladeLieferanten(); } catch (f) { /* geht auch ohne */ }
  try { bezeichnungen = await ladeBezeichnungen(); } catch (f) { /* geht auch ohne */ }

  const w = await dialogFelder({
    titel: "Neuen Artikel anlegen",
    felder: [
      { name: "nummer", label: "Artikelnummer", pflicht: true, wert: vorgabe || "" },
      { name: "beschreibung", label: "Beschreibung", typ: "textarea",
        platzhalter: "nur falls nötig, kann leer bleiben" },
    ],
    bestaetigen: "Weiter",
  });
  if (!w) return null;

  // Bezeichnung aus der gepflegten Liste wählen
  const bez = await bezeichnungWaehlen(bezeichnungen);
  if (bez === null) return null;
  w.name = bez;

  let lieferantId = null;
  // Ein Lieferant ist Pflicht. Die Abfrage wiederholt sich,
  // bis wirklich einer gewählt oder neu angelegt wurde.
  let wahl = lieferantVorgabe || null;
  while (!wahl) {
    const auswahlListe = lieferanten.map((l) => ({ wert: l.id, text: l.name, such: l.name }))
      .concat([{ wert: "__neu", text: "+ Neuen Lieferanten anlegen", such: "neu" }]);

    wahl = auswahlListe.length > 12
      ? await auswahlSuchen("Lieferant wählen (Pflicht)", auswahlListe)
      : await auswahlDialog("Lieferant wählen (Pflicht)", auswahlListe);

    if (wahl === null) return null;   // ganz abgebrochen
    if (!wahl) { wahl = null; continue; }   // leer gewählt, nochmal fragen
  }

  if (wahl === "__neu") {
    const nw = await dialogFelder({ titel: "Neuer Lieferant",
      felder: [
        { name: "name", label: "Name", pflicht: true },
        { name: "website", label: "Website", platzhalter: "www.beispiel.ch",
          hinweis: "Der Name wird dann überall in der App anklickbar." },
      ], bestaetigen: "Anlegen" });
    if (nw) {
      let seite = (nw.website || "").trim();
      if (seite && !/^https?:\/\//i.test(seite)) seite = "https://" + seite;
      const r = await db.from("suppliers")
        .insert({ name: nw.name, website: seite || null }).select().single();
      if (r.error) meldung(fehlertext(r.error), "fehler");
      else { lieferantId = r.data.id; lieferanten.push(r.data); meldung("Lieferant angelegt."); }
    } else {
      return null;
    }
  } else {
    lieferantId = wahl;
  }

  if (!lieferantId) {
    meldung("Ohne Lieferant lässt sich der Artikel nicht anlegen.", "warn");
    return null;
  }

  const { data, error } = await db.from("articles").insert({
    article_number: w.nummer, name: w.name,
    description: (w.beschreibung || "").trim() || null,
    unit: "Stück", supplier_id: lieferantId,
  }).select().single();

  if (error) {
    const m = String(error.message || "").toLowerCase();
    if (m.includes("duplicate") || m.includes("unique")) {
      // Der Artikel gibt es schon, taucht aber vielleicht nicht in der
      // Liste auf, weil er ausgeblendet ist. Also holen und anbieten.
      const alt = await db.from("articles").select("*")
        .eq("article_number", w.nummer).maybeSingle();

      if (alt.data) {
        const ok = await nachfragen({
          titel: "Artikel gibt es bereits",
          text: alt.data.article_number + " · " + (alt.data.name || "")
              + (alt.data.is_active === false
                  ? " — er ist zurzeit ausgeblendet, deshalb siehst du ihn nicht in der Liste."
                  : "")
              + " Soll dieser Artikel verwendet werden?",
          bestaetigen: "Diesen verwenden" });

        if (!ok) return null;

        if (alt.data.is_active === false) {
          await db.from("articles").update({ is_active: true }).eq("id", alt.data.id);
        }

        const lief2 = lieferanten.find((l) => l.id === alt.data.supplier_id);
        return { id: alt.data.id, article_number: alt.data.article_number,
                 name: alt.data.name, supplier_id: alt.data.supplier_id,
                 supplier_name: lief2 ? lief2.name : null, unit: "Stück" };
      }
    }
    meldung(fehlertext(error), "fehler");
    return null;
  }
  meldung("Artikel angelegt.");

  const lief = lieferanten.find((l) => l.id === lieferantId);
  return { id: data.id, article_number: data.article_number, name: data.name,
           supplier_id: data.supplier_id, supplier_name: lief ? lief.name : null,
           unit: data.unit, gesamtbestand: 0 };
}

// Einfache Auswahl aus einer Liste. Gibt den gewählten Wert zurück.
// Auswahl mit Suchfeld, für lange Listen
function auswahlSuchen(titel, optionen, mindestens) {
  return new Promise((fertig) => {
    const h = document.createElement("div");
    h.className = "dialog-huelle";
    h.innerHTML = '<div class="dialog"><h2>' + esc(titel) + '</h2>'
      + '<div class="suchleiste"><input type="search" id="as-suche"'
      + ' placeholder="Suchen" autocomplete="off"></div>'
      + '<div class="statuswahl" id="as-liste"></div>'
      + '<div class="dialog__knoepfe">'
      + '<button class="knopf knopf--still" data-nein>Abbrechen</button></div></div>';
    document.body.appendChild(h);

    const zu = (v) => { h.remove(); fertig(v); };
    h.querySelector("[data-nein]").onclick = () => zu(null);
    dialogSchliessen(h, () => zu(null));

    const liste = h.querySelector("#as-liste");
    const feld = h.querySelector("#as-suche");

    const zeichnen = () => {
      const t = (feld.value || "").trim().toLowerCase();
      const treffer = optionen.filter((o) => !t || o.text.toLowerCase().includes(t));
      liste.innerHTML = treffer.length
        ? treffer.slice(0, 40).map((o) => '<button class="knopf" data-w="' + esc(o.wert)
            + '">' + esc(o.text) + '</button>').join("")
        : '<p class="hinweis">Nichts gefunden.</p>';
      liste.querySelectorAll("[data-w]").forEach((k) => { k.onclick = () => zu(k.dataset.w); });
    };

    feld.oninput = zeichnen;
    zeichnen();
    feld.focus();
  });
}

