    "}",
    "function emlBauen(pdfB64) {",
    "  var t = Date.now(), gM = '----=_Hofer_M' + t, gR = '----=_Hofer_R' + t, gA = '----=_Hofer_A' + t;",
    "  var name = MAIL.datei + '.pdf';",
    "  var teile = [",
    "    'To: ' + MAIL.an,",
    "    'Subject: =?UTF-8?B?' + b64(MAIL.betreff) + '?=',",
