    "  (MAIL.logos || []).forEach(function (l) {",
    "    teile.push('--' + gR, 'Content-Type: image/png; name=\"' + l.datei + '\"',",
    "      'Content-Transfer-Encoding: base64', 'Content-ID: <' + l.id + '>',",
    "      'Content-Disposition: inline; filename=\"' + l.datei + '\"', '', zeilen76(l.bild), '');",
    "  });",
    "  teile.push('--' + gR + '--', '',",
    "    '--' + gM,",
    "    'Content-Type: application/pdf; name=\"' + name + '\"',",
    "    'Content-Disposition: attachment; filename=\"' + name + '\"',",
    "    'Content-Transfer-Encoding: base64',",
    "    '',",
