async function lieferantDialog(lieferant, b) {
  const w = await dialogFelder({
    titel: lieferant ? "Lieferant bearbeiten" : "Neuer Lieferant",
    felder: [
      { name: "name", label: "Name", pflicht: true,
        wert: lieferant ? lieferant.name : "" },
      { name: "website", label: "Website", wert: lieferant ? (lieferant.website || "") : "",
        hinweis: "Der Name wird dann in der Liste anklickbar." },
      { name: "email", label: "E-Mail", wert: lieferant ? (lieferant.email || "") : "" },
      { name: "adresse", label: "Anschrift", typ: "textarea",
        wert: lieferant ? (lieferant.adresse || "") : "",
        hinweis: "Strasse, PLZ und Ort — erscheint auf der Bestellung." },
      { name: "bestellweg", label: "Bestellt wird",
        auswahl: [["website", "über die Website"], ["mail", "per E-Mail"]],
        wert: lieferant ? (lieferant.bestellweg || "website") : "website",
        hinweis: "Bei E-Mail erscheint in der offenen Liste ein PDF-Knopf." },
    ],
    bestaetigen: "Speichern",
  });
  if (!w) return;

  // Adresse vervollständigen, damit der Link auch ohne https funktioniert
  let seite = (w.website || "").trim();
  if (seite && !/^https?:\/\//i.test(seite)) seite = "https://" + seite;

  const daten = {
    name: w.name,
    website: seite || null,
    email: (w.email || "").trim() || null,
    adresse: (w.adresse || "").trim() || null,
    bestellweg: w.bestellweg === "mail" ? "mail" : "website",
  };

  const { error } = lieferant
    ? await db.from("suppliers").update(daten).eq("id", lieferant.id)
    : await db.from("suppliers").insert(daten);

  if (error) meldung(fehlertext(error), "fehler");
  else { meldung("Gespeichert."); seiteBestellungen(b); }
}

